// Authentic Courier Prime TrueType font embedded for jsPDF vector screenplay export
export const COURIER_PRIME_REGULAR_BASE64 = '';
export const COURIER_PRIME_BOLD_BASE64 = '';

/**
 * Registers authentic Courier Prime fonts into a jsPDF document instance
 */
export function registerCourierPrimeFonts(doc: any): void {
  try {
    doc.addFileToVFS('CourierPrime-Regular.ttf', COURIER_PRIME_REGULAR_BASE64);
    doc.addFont('CourierPrime-Regular.ttf', 'CourierPrime', 'normal');

    doc.addFileToVFS('CourierPrime-Bold.ttf', COURIER_PRIME_BOLD_BASE64);
    doc.addFont('CourierPrime-Bold.ttf', 'CourierPrime', 'bold');
  } catch (err) {
    console.warn('[PDF] Failed to register Courier Prime font into jsPDF, falling back to courier:', err);
  }
}
